package com.bank.rw.context;

// Holds the current route (PRIMARY/REPLICA) for this thread/request.
public final class DbContextHolder {
    public enum Route { PRIMARY, REPLICA }
    private static final ThreadLocal<Route> CTX = new ThreadLocal<>();

    public static void set(Route r) { CTX.set(r); }
    public static Route get() { return CTX.get(); }
    public static void clear() { CTX.remove(); }   // MUST clear to avoid leaking to next request
    private DbContextHolder() {}
}
