package com.bank.rw.config;

import com.bank.rw.context.DbContextHolder;
import org.springframework.jdbc.datasource.lookup.AbstractRoutingDataSource;
import org.springframework.transaction.support.TransactionSynchronizationManager;

// Picks PRIMARY or REPLICA at connection time based on the readOnly transaction flag.
public class RoutingDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        // Explicit override wins (e.g. forced fresh read)...
        DbContextHolder.Route forced = DbContextHolder.get();
        if (forced != null) return forced;
        // ...otherwise route read-only transactions to the replica, everything else to primary.
        boolean readOnly = TransactionSynchronizationManager.isCurrentTransactionReadOnly();
        return readOnly ? DbContextHolder.Route.REPLICA : DbContextHolder.Route.PRIMARY;
    }
}
