package com.bank.rw.config;

import com.bank.rw.context.DbContextHolder;
import com.zaxxer.hikari.HikariDataSource;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.*;
import org.springframework.jdbc.datasource.LazyConnectionDataSourceProxy;
import javax.sql.DataSource;
import java.util.HashMap;
import java.util.Map;

@Configuration
public class DataSourceConfig {

    @Bean @ConfigurationProperties("spring.datasource.primary")
    public DataSource primaryDataSource() { return new HikariDataSource(); }

    @Bean @ConfigurationProperties("spring.datasource.replica")
    public DataSource replicaDataSource() { return new HikariDataSource(); }

    @Bean
    public DataSource routingDataSource(DataSource primaryDataSource, DataSource replicaDataSource) {
        RoutingDataSource routing = new RoutingDataSource();
        Map<Object, Object> targets = new HashMap<>();
        targets.put(DbContextHolder.Route.PRIMARY, primaryDataSource);
        targets.put(DbContextHolder.Route.REPLICA, replicaDataSource);
        routing.setTargetDataSources(targets);
        routing.setDefaultTargetDataSource(primaryDataSource);   // safe default: PRIMARY
        routing.afterPropertiesSet();
        // Lazy proxy so the route is resolved when the connection is actually needed.
        return new LazyConnectionDataSourceProxy(routing);
    }
}
