package com.bank.rw.service;

import com.bank.rw.context.DbContextHolder;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class AccountService {
    private static final Logger log = LoggerFactory.getLogger(AccountService.class);
    private final JdbcTemplate jdbc;

    public AccountService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    // WRITE → not readOnly → routed to PRIMARY automatically.
    @Transactional
    public void transfer(String fromId, String toId, BigDecimal amount) {
        jdbc.update("UPDATE accounts SET balance = balance - ? WHERE account_id = ?", amount, fromId);
        jdbc.update("UPDATE accounts SET balance = balance + ? WHERE account_id = ?", amount, toId);
        log.info("transfer {} {}->{} on PRIMARY", amount, fromId, toId);
    }

    // READ → readOnly → routed to REPLICA automatically (offloads primary).
    @Transactional(readOnly = true)
    public BigDecimal balance(String accountId) {
        BigDecimal b = jdbc.queryForObject(
            "SELECT balance FROM accounts WHERE account_id = ?", BigDecimal.class, accountId);
        log.info("balance {} read from REPLICA = {}", accountId, b);
        return b;
    }

    // MUST-BE-FRESH read (e.g. right after a transfer): force PRIMARY to avoid stale replica.
    public BigDecimal freshBalance(String accountId) {
        DbContextHolder.set(DbContextHolder.Route.PRIMARY);   // override routing
        try {
            BigDecimal b = jdbc.queryForObject(
                "SELECT balance FROM accounts WHERE account_id = ?", BigDecimal.class, accountId);
            log.info("fresh balance {} read from PRIMARY = {}", accountId, b);
            return b;
        } finally {
            DbContextHolder.clear();   // always clear the forced route
        }
    }
}
